mapper.select:
SELECT s.* FROM app_user_current_student cs
JOIN student s ON s.id = cs.student_id
WHERE cs.user_id = #{userId}

mapper.update:
UPDATE student SET name=#{name}, gender=#{gender}, age=#{age}, class_name=#{className},
  disability_type=#{disabilityType}, remark=#{remark},
  social_adaptation=#{socialAdaptation}, self_management=#{selfManagement},
  cognitive_level=#{cognitiveLevel}, language_comprehension=#{languageComprehension},
  expression_ability=#{expressionAbility}, hobbies=#{hobbies}
WHERE id=#{id}

mapper.select:
SELECT COUNT(*) > 0
FROM app_user_student
WHERE user_id = #{userId} AND student_id = #{studentId}
